class Solution {
public:
    bool isPalindrome(int x) {
        // 负数带负号；非 0 的整十数首位不可能是 0，两者必非回文
        if (x < 0 || (x % 10 == 0 && x != 0)) return false;
        int rev = 0;
        while (x > rev) {              // 只反转后一半：x 不断砍末位，rev 不断接末位
            rev = rev * 10 + x % 10;   // 位技巧：x % 10 取个位，接到 rev 末尾
            x /= 10;                   // 位技巧：x /= 10 砍掉个位
        }
        // 偶数位直接相等；奇数位 rev 多一位中间位，去掉再比
        return x == rev || x == rev / 10;
    }
};

