    def f(x: float, n: int) -> float:
        if n == 0:
            return 1.0
        half = f(x, n // 2)     # 先算一半：指数减半
        if n % 2 == 0:
            return half * half  # 偶数：平方即可
        return half * half * x  # 奇数：补乘一个 x
    if n < 0:
        x = 1 / x
        n = -n
    return f(x, n)

