class Solution {
public:
    vector<int> plusOne(vector<int>& digits) {
        // 从最低位向高位扫：第一个非 9 位直接 +1，进位到此为止
        for (int i = (int)digits.size() - 1; i >= 0; --i) {
            if (digits[i] < 9) {
                digits[i] += 1;      // 收下进位，高位完全不变
                return digits;
            }
            digits[i] = 0;           // 是 9 则变 0，继续向高位进位
        }
        // 循环走完说明全是 9：如 999 -> 1000，结果比原数组多一位
        digits.insert(digits.begin(), 1);
        return digits;
    }
};

