// ACM 模式：完整可运行程序（stdin -> stdout）
// 输入格式：
//   第一行：n（位数）
//   第二行：n 个数字（0-9），空格分隔，最高位在前
// 输出格式：一行，加一后的各位数字，空格分隔
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);   // 关闭同步，读入更快
    cin.tie(nullptr);

    int n;
    cin >> n;
    vector<int> digits(n);
    for (auto& d : digits) cin >> d;

    bool carry = true;             // 加一相当于最低位带进位 1
    for (int i = n - 1; i >= 0; --i) {
        if (digits[i] < 9) {       // 第一个非 9 位收下进位，高位完全不变
            digits[i] += 1;
            carry = false;
            break;
        }
        digits[i] = 0;             // 是 9 则变 0，继续向高位进位
    }
    if (carry) digits.insert(digits.begin(), 1);  // 全 9：最高位再进一位

    for (int i = 0; i < (int)digits.size(); ++i) {
        if (i) cout << ' ';        // 空格分隔
        cout << digits[i];
    }
    cout << endl;
    return 0;
}

