class Solution {
public:
    int mySqrt(int x) {
        int left = 0, right = x;               // 答案落在 [0, x]，x < 2 时结果就是 x 本身
        while (left <= right) {
            int mid = left + (right - left) / 2;   // 取中点，防 left+right 相加溢出
            // 用 long long 承接乘积，防 mid*mid 溢出 int
            if ((long long)mid * mid <= x) left = mid + 1;   // mid 可行，往右找更大的
            else right = mid - 1;                            // mid 偏大，收缩右边界
        }
        // right 停在最后一个满足 mid*mid <= x 的值（left 已越过可行域一格）
        return right;
    }
};

