class Solution {
    public int maxPoints(int[][] points) {
        int n = points.length;
        if (n <= 2) return n;      // 不超过 2 个点必然共线
        int ans = 0;
        for (int i = 0; i < n; i++) {
            // 以 i 为锚点：最简斜率比编码成一个 long 作 key -> 同斜率点数
            Map<Long, Integer> cnt = new HashMap<>();
            for (int j = i + 1; j < n; j++) {
                int dx = points[j][0] - points[i][0];
                int dy = points[j][1] - points[i][1];
                int g = gcd(Math.abs(dx), Math.abs(dy));  // 自实现 gcd，返回非负数
                dx /= g; dy /= g;   // 约分成最简整数比，避免浮点误差
                // 统一符号：(1,-2) 与 (-1,2) 是同一斜率
                if (dx < 0 || (dx == 0 && dy < 0)) { dx = -dx; dy = -dy; }
                // 坐标差绝对值 <= 2*10^4 < 40001/2，该编码不会碰撞
                long key = (long) dx * 40001L + dy;
                cnt.merge(key, 1, Integer::sum);
                ans = Math.max(ans, cnt.get(key) + 1);   // +1 是锚点自己
            }
        }
        return ans;
    }

    private int gcd(int a, int b) {
        // 欧几里得算法：辗转相除求最大公约数
        return b == 0 ? a : gcd(b, a % b);
    }
}

