var maxPoints = function (points) {
  const gcd = (a, b) => { // 欧几里得算法：辗转相除求最大公约数
    while (b) {
      const t = a % b;
      a = b;
      b = t;
    }
    return a;
  };
  const n = points.length;
  if (n <= 2) return n;   // 不超过 2 个点必然共线
  let ans = 0;
  for (let i = 0; i < n; i++) {
