      let dy = points[j][1] - points[i][1];
      const g = gcd(Math.abs(dx), Math.abs(dy)); // 自实现 gcd，返回非负数
      dx /= g; // g 整除 dx，除法结果精确为整数
      dy /= g;
      // 统一符号：(1,-2) 与 (-1,2) 是同一斜率
      if (dx < 0 || (dx === 0 && dy < 0)) {
        dx = -dx;
        dy = -dy;
