def missingNumber_sort(nums):
    nums.sort()                  # 排序后从缺失处开始错位
    for i, x in enumerate(nums):
        if x != i:               # 第一个错位点就是缺失数
            return i
    return len(nums)             # 全部匹配，缺的是 n

def missingNumber_set(nums):
    seen = set(nums)             # O(1) 存在性查询
    for i in range(len(nums) + 1):   # 范围 0..n，含 n
        if i not in seen:
            return i
    return -1                    # 题目保证有解，此行仅为完整性

def missingNumber_sum(nums):
    n = len(nums)
    return n * (n + 1) // 2 - sum(nums)   # 0..n 的期望和减去实际和

def missingNumber_xor(nums):
    ans = len(nums)              # 下标只有 0..n-1，先把边界值 n 补进异或
    for i, x in enumerate(nums):
        ans ^= i ^ x             # 值与下标成对出现则互相抵消，x^x=0
    return ans                   # 唯一缺失的数没有配对下标，保留下来

